<template>
  <section class="space-y-5"><div><p class="text-xs font-bold uppercase tracking-wider text-blue-300">Delivery operations</p><h1 class="mt-1 text-3xl font-bold text-white">Assigned work tasks</h1></div><div class="flex gap-2"><button v-for="tab in tabs" :key="tab.key" class="rounded-lg border px-4 py-2 text-sm" :class="active===tab.key?'border-blue-400/40 bg-blue-500/15 text-blue-200':'border-white/10 text-slate-400'" @click="active=tab.key">{{ tab.label }}</button></div><NuxtLink v-for="item in filtered" :key="item.id" :to="`/partner/tasks/${item.id}`" class="pc-card flex flex-wrap items-start justify-between gap-4"><div><p class="font-semibold capitalize text-white">{{ label(item.task_type||'service task') }}</p><p class="mt-1 text-sm text-slate-400">{{ item.project_title||item.device_name||'Project pending' }}</p><p class="mt-3 text-xs text-slate-500">{{ item.project_region||'Region pending' }} · due {{ item.due_date||'not set' }}</p></div><span class="rounded-full bg-blue-500/10 px-3 py-1 text-xs uppercase text-blue-300">{{ label(item.status) }}</span></NuxtLink><p v-if="error" class="pc-card text-red-300">{{ error }}</p><p v-if="!filtered.length&&!error" class="pc-card text-slate-500">No tasks in this view.</p></section>
</template>
<script setup lang="ts">
definePageMeta({layout:'partner-workspace',middleware:['auth']});const {apiFetch}=useApi();const items=ref<any[]>([]);const active=ref('open');const error=ref('');const tabs=[{key:'open',label:'Open'},{key:'all',label:'All'},{key:'in_progress',label:'In progress'},{key:'done',label:'Done'}];const label=(v:string)=>v?.replaceAll('_',' ')||'unknown';const filtered=computed(()=>active.value==='all'?items.value:active.value==='open'?items.value.filter(x=>['scheduled','due','in_progress','completed_pending_acceptance'].includes(x.status)):items.value.filter(x=>x.status===active.value));onMounted(async()=>{try{items.value=(await apiFetch<any>('/partner/tasks?limit=100')).items||[]}catch(e:any){error.value=e?.data?.detail||e?.message}})
</script>
